import subprocess

def handle(query, state):
    flag = state["flag"]
    filename = (query.get("file") or [""])[0]
    if not filename:
        return 200, {"Content-Type": "text/plain"}, "Usage: ?file=<filename>"
    try:
        result = subprocess.run(
            f"cat {filename}",
            shell=True,
            capture_output=True,
            text=True,
            timeout=3
        )
        return 200, {"Content-Type": "text/plain"}, result.stdout
    except subprocess.TimeoutExpired:
        return 500, {"Content-Type": "text/plain"}, "Timeout"
    except Exception as e:
        return 500, {"Content-Type": "text/plain"}, "Error: " + str(e)
